  const lines = ["\u3010\u672C\u8F6E\u68C0\u5B9A\u7ED3\u679C\u3011\u4EE5\u4E0B\u7ED3\u679C\u5DF2\u7ECF\u53D1\u751F\uFF0C\u6B63\u6587\u5FC5\u987B\u4E0E\u4E4B\u4E00\u81F4\u3002"];
